#!/usr/bin/env python3
"""Writes src/models/qwen35/draft_vocab.cpp: the top --size token ids of a
ranking from rank_tokens.py, as a bitmap of base64 characters.

  python3 tools/draft_vocab/make_table.py --ranking ranking.txt \
      --size 32768 --out src/models/qwen35/draft_vocab.cpp
  python3 tools/ci/check-format.py --fix
"""

import argparse
import pathlib

ALPHABET = ("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
            "0123456789+/")

HEADER = """\
// Generated by tools/draft_vocab/make_table.py from the ranking of
// tools/draft_vocab/rank_tokens.py (top {size} tokens); do not edit.
#include "models/qwen35/draft_vocab.hpp"

#include <stdexcept>
#include <string_view>

namespace gufo_npu::qwen35 {{
namespace {{

// The ids as a bitmap, six per character: the character's index in the
// base64 alphabet, low bit first.
constexpr std::string_view kAlphabet =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
constexpr std::string_view kBitmap =
{body};

}}  // namespace

std::vector<int> DraftVocab(int vocab) {{
  std::vector<int> ids;
  ids.reserve({size});
  for (std::size_t i = 0; i < kBitmap.size(); ++i) {{
    const auto bits = kAlphabet.find(kBitmap[i]);
    for (int b = 0; b < 6; ++b) {{
      if ((bits >> b) & 1) {{
        ids.push_back(static_cast<int>(i) * 6 + b);
      }}
    }}
  }}
  if (!ids.empty() && ids.back() >= vocab) {{
    throw std::runtime_error("qwen35: draft vocabulary id beyond the vocab");
  }}
  return ids;
}}

}}  // namespace gufo_npu::qwen35
"""


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    parser.add_argument("--ranking", type=pathlib.Path, required=True)
    parser.add_argument("--size", type=int, required=True)
    parser.add_argument("--out", type=pathlib.Path, required=True)
    args = parser.parse_args()
    ranked = [int(line) for line in args.ranking.read_text().split()]
    ids = sorted(ranked[:args.size])
    members = set(ids)
    chars = [
        ALPHABET[sum(1 << b for b in range(6) if start + b in members)]
        for start in range(0, ids[-1] + 1, 6)
    ]
    text = "".join(chars)
    width = 72
    body = "\n".join(f'    "{text[i:i + width]}"'
                     for i in range(0, len(text), width))
    args.out.write_text(HEADER.format(size=len(ids), body=body))
    print(f"{len(ids)} ids in {len(text)} characters -> {args.out}")


if __name__ == "__main__":
    main()
